window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e23111f5b9f425ce"]={"versions": [{"id": "FIG-e23111f5b9f425ce", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenlayout-Diagramm zur Darstellung des Rückkopierens von E2E-Prüfdaten (CRC und Alive-Counter) aus einer I-PDU-Kopie in Datenelemente einer AUTOSAR-Software-Komponente (SW-C). Es veranschaulicht das Zusammenspiel zwischen dem serialisierten PDU-Puffer (unten) und der C-Struktur bzw. den Datenelementen der Applikationsebene (oben).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>C-Struktur / Datenelemente (oben)</strong>:</li>\n<li><code>crc</code>: Zusätzliches Datenelement, durch die SW-C ungenutzt (<code>/<em> additional data el, unused by SW-C </em>/</code>).</li>\n<li><code>counter</code>: Zusätzliches Datenelement, durch die SW-C ungenutzt (<code>/<em> additional data el, unused by SW-C </em>/</code>).</li>\n<li><code>speed</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU belegt werden (<code>/<em> 16-bit, but 12 bits used in I-PDU </em>/</code>).</li>\n<li><code>accel</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU belegt werden (<code>/<em> 16-bit, but 12 bits used in I-PDU </em>/</code>).</li>\n<li><strong>I-PDU-Kopie / Serialisierter Byte-Stream (unten)</strong>:</li>\n<li>Byte- bzw. Bitfelder mit den Abschnitten <code>CRC</code>, <code>accel</code>, <code>counter</code>, <code>speed</code>, einem Leerbereich sowie statischen/vordefinierten Byte-Werten (<code>0xF0</code>, <code>0xFF</code>).</li>\n<li><strong>Verbindungsrelationen</strong>:</li>\n<li>Gerichteter Pfeil von dem <code>CRC</code>-Feld der I-PDU zum Datenelement <code>crc</code>.</li>\n<li>Gerichteter Pfeil von dem <code>counter</code>-Feld der I-PDU zum Datenelement <code>counter</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der empfangenen bzw. zwischengespeicherten I-PDU-Kopie im Kommunikationspuffer.</li>\n<li>Extraktion des Prüfwerts (<code>CRC</code>) aus dem entsprechenden Feld der I-PDU und Rückkopieren in das C-Datenelement <code>crc</code>.</li>\n<li>Extraktion des Zählerwerts (<code>counter</code>) aus dem entsprechenden Bit-/Bytefeld der I-PDU und Rückkopieren in das C-Datenelement <code>counter</code>.</li>\n<li>Weiterleitung bzw. Bereitstellung der Daten an die E2E-Bibliotheksfunktionen (z. B. <code>E2E_P01Check</code> o. ä.) zur Konsistenz- und Gültigkeitsprüfung der Nutzdaten (<code>speed</code>, <code>accel</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht das Integrationsmuster für E2E-Schutzmechanismen, bei dem E2E-Metadaten (CRC, Alive Counter) über generierte Datenstrukturen transportiert werden, ohne dass die Anwendungslogik der SW-C diese direkt konsumiert.</li>\n<li>Entwickler müssen sicherstellen, dass die Mapping-Konfiguration in COM bzw. RTE die Rückkopierung der Protokollsteuerdaten in die dedizierten Struct-Member exakt auf die Bitpositionen der I-PDU ausrichtet.</li>\n<li>Dient als Vorlage für Protokollabwicklungen, bei denen der E2E-Check auf Ebene von SW-C-/RTE-Datenelementen stattfindet.</li>\n</ul>"}, {"id": "FIG-1529bef4357cfa52", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenlayout-Diagramm zur Darstellung des Rückkopierens von E2E-Prüfdaten (CRC und Alive-Counter) aus einer I-PDU-Kopie in Datenelemente einer AUTOSAR-Software-Komponente (SW-C). Es veranschaulicht das Zusammenspiel zwischen dem serialisierten PDU-Puffer (unten) und der C-Struktur bzw. den Datenelementen der Applikationsebene (oben).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>C-Struktur / Datenelemente (oben)</strong>:</li>\n<li><code>crc</code>: Zusätzliches Datenelement, durch die SW-C ungenutzt (<code>/<em> additional data el, unused by SW-C </em>/</code>).</li>\n<li><code>counter</code>: Zusätzliches Datenelement, durch die SW-C ungenutzt (<code>/<em> additional data el, unused by SW-C </em>/</code>).</li>\n<li><code>speed</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU belegt werden (<code>/<em> 16-bit, but 12 bits used in I-PDU </em>/</code>).</li>\n<li><code>accel</code>: 16-Bit-Datenelement, wovon 12 Bits in der I-PDU belegt werden (<code>/<em> 16-bit, but 12 bits used in I-PDU </em>/</code>).</li>\n<li><strong>I-PDU-Kopie / Serialisierter Byte-Stream (unten)</strong>:</li>\n<li>Byte- bzw. Bitfelder mit den Abschnitten <code>CRC</code>, <code>accel</code>, <code>counter</code>, <code>speed</code>, einem Leerbereich sowie statischen/vordefinierten Byte-Werten (<code>0xF0</code>, <code>0xFF</code>).</li>\n<li><strong>Verbindungsrelationen</strong>:</li>\n<li>Gerichteter Pfeil von dem <code>CRC</code>-Feld der I-PDU zum Datenelement <code>crc</code>.</li>\n<li>Gerichteter Pfeil von dem <code>counter</code>-Feld der I-PDU zum Datenelement <code>counter</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der empfangenen bzw. zwischengespeicherten I-PDU-Kopie im Kommunikationspuffer.</li>\n<li>Extraktion des Prüfwerts (<code>CRC</code>) aus dem entsprechenden Feld der I-PDU und Rückkopieren in das C-Datenelement <code>crc</code>.</li>\n<li>Extraktion des Zählerwerts (<code>counter</code>) aus dem entsprechenden Bit-/Bytefeld der I-PDU und Rückkopieren in das C-Datenelement <code>counter</code>.</li>\n<li>Weiterleitung bzw. Bereitstellung der Daten an die E2E-Bibliotheksfunktionen (z. B. <code>E2E_P01Check</code> o. ä.) zur Konsistenz- und Gültigkeitsprüfung der Nutzdaten (<code>speed</code>, <code>accel</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht das Integrationsmuster für E2E-Schutzmechanismen, bei dem E2E-Metadaten (CRC, Alive Counter) über generierte Datenstrukturen transportiert werden, ohne dass die Anwendungslogik der SW-C diese direkt konsumiert.</li>\n<li>Entwickler müssen sicherstellen, dass die Mapping-Konfiguration in COM bzw. RTE die Rückkopierung der Protokollsteuerdaten in die dedizierten Struct-Member exakt auf die Bitpositionen der I-PDU ausrichtet.</li>\n<li>Dient als Vorlage für Protokollabwicklungen, bei denen der E2E-Check auf Ebene von SW-C-/RTE-Datenelementen stattfindet.</li>\n</ul>"}], "trans": [{"from": "FIG-e23111f5b9f425ce", "to": "FIG-1529bef4357cfa52", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
